import java.util.ArrayList;
import java.util.List;

public class RouteHistoryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            List<String> source = new ArrayList<>();
            source.add("depot");
            source.add("mill");
            source.add("   ");
            source.add(null);

            RouteHistory original = new RouteHistory("ann", source);
            check("blank and null stops skipped", 2, original.stopCount());
            check("route text", "depot -> mill", original.route());

            source.add("sneaky");
            check("caller's list is not shared", 2, original.stopCount());

            RouteHistory copy = new RouteHistory(original);
            check("copy starts identical", "depot -> mill", copy.route());
            check("copy carries the driver", "ann", copy.getDriver());
            check("copy reports the same route", true, copy.sameRouteAs(original));

            copy.addStop("quay");
            copy.setDriver("bob");
            check("original route untouched", "depot -> mill", original.route());
            check("original driver untouched", "ann", original.getDriver());
            check("copy grew", "depot -> mill -> quay", copy.route());
            check("routes now differ", false, copy.sameRouteAs(original));

            original.addStop("");
            check("blank stop refused", false, original.addStop(null));
            check("original still has two stops", 2, original.stopCount());

            RouteHistory blank = new RouteHistory("cid", null);
            check("null list gives an empty route", "(empty)", blank.route());
            RouteHistory blankCopy = new RouteHistory(blank);
            check("copy of an empty route", "(empty)", blankCopy.route());
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

