import java.util.ArrayList;
import java.util.List;

public class RouteHistory {

    private String driver;
    private final List<String> stops = new ArrayList<>();

    public RouteHistory(String driver, List<String> stops) {
        this.driver = driver;
        if (stops != null) {
            for (String stop : stops) {
                addStop(stop);
            }
        }
    }

    public RouteHistory(RouteHistory other) {
        this.driver = other.driver;
        this.stops.addAll(other.stops);
    }

    public boolean addStop(String name) {
        if (name == null || name.trim().isEmpty()) {
            return false;
        }
        stops.add(name);
        return true;
    }

    public void setDriver(String driver) {
        this.driver = driver;
    }

    public String getDriver() {
        return driver;
    }

    public int stopCount() {
        return stops.size();
    }

    public String route() {
        if (stops.isEmpty()) {
            return "(empty)";
        }
        return String.join(" -> ", stops);
    }

    public boolean sameRouteAs(RouteHistory other) {
        return other != null && stops.equals(other.stops);
    }
}
